{
  "path": "supabase/functions/process-tasks/index.ts",
  "contents": "import 'jsr:@supabase/functions-js/edge-runtime.d.ts'
import { createClient } from 'npm:@supabase/supabase-js@2.49.8'

const supabase = createClient(
  Deno.env.get('SUPABASE_URL') ?? 'http://127.0.0.1:54321',
  Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,
)

const QUEUE_NAME = 'tasks'
const BATCH_SIZE = 10

interface QueueMessage {
  msg_id: number | string
  message: unknown
}

Deno.serve(async (req) => {
  if (req.method !== 'POST') {
    return new Response('expected POST request', { status: 405 })
  }

  const { data: messages, error: readError } = await supabase
    .schema('pgmq_public')
    .rpc('read', {
      queue_name: QUEUE_NAME,
      sleep_seconds: 30,
      n: BATCH_SIZE,
    })

  if (readError) {
    console.error('failed to read tasks queue:', readError)
    return Response.json({ error: readError.message }, { status: 500 })
  }

  const deleted: Array<number | string> = []
  const errors: Array<{ msg_id: number | string; error: string }> = []

  for (const message of (messages ?? []) as QueueMessage[]) {
    try {
      // Task-specific work can be added here. A successful pass removes the message.
      const { error: deleteError } = await supabase
        .schema('pgmq_public')
        .rpc('delete', {
          queue_name: QUEUE_NAME,
          message_id: message.msg_id,
        })

      if (deleteError) throw deleteError
      deleted.push(message.msg_id)
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error)
      console.error(`failed to delete task ${message.msg_id}:`, detail)
      errors.push({ msg_id: message.msg_id, error: detail })
    }
  }

  return Response.json({
    queue: QUEUE_NAME,
    read: messages?.length ?? 0,
    deleted,
    errors,
  })
})
"
}

